begin;
select plan(36);
select set_config('test.owner',gen_random_uuid()::text,true);
select set_config('test.staff',gen_random_uuid()::text,true);
select set_config('test.client',gen_random_uuid()::text,true);
select set_config('test.pet',gen_random_uuid()::text,true);
select set_config('test.employee',gen_random_uuid()::text,true);
select set_config('test.service',gen_random_uuid()::text,true);
insert into auth.users(id,email,raw_user_meta_data) values(current_setting('test.owner')::uuid,'test-'||current_setting('test.owner')||'@example.test','{}'),(current_setting('test.staff')::uuid,'test-'||current_setting('test.staff')||'@example.test','{}');
insert into public.user_roles select current_setting('test.owner')::uuid,id from public.roles where code='OWNER';
insert into public.user_roles select current_setting('test.staff')::uuid,id from public.roles where code='STAFF';
insert into public.clients(id,first_name) values(current_setting('test.client')::uuid,'Fixture agenda');
insert into public.pets(id,client_id,name) values(current_setting('test.pet')::uuid,current_setting('test.client')::uuid,'Fixture perro');
insert into public.employees(id,profile_id,skill_level) values(current_setting('test.employee')::uuid,current_setting('test.owner')::uuid,'ALL_SERVICES');
insert into public.employee_schedules(employee_id,weekday,start_time,end_time) values(current_setting('test.employee')::uuid,2,'07:00','19:00');
insert into public.services(id,name,base_price,base_duration_minutes,requires_specialist) values(current_setting('test.service')::uuid,'Fixture baño/corte',100.10,120,true);
select set_config('test.payload',jsonb_build_object('client_id',current_setting('test.client'),'items',jsonb_build_array(jsonb_build_object('pet_id',current_setting('test.pet'),'service_id',current_setting('test.service'),'stages',jsonb_build_array(
 jsonb_build_object('employee_id',current_setting('test.employee'),'stage','BATH','starts_local','2030-07-30T17:00','ends_local','2030-07-30T18:00'),
 jsonb_build_object('employee_id',current_setting('test.employee'),'stage','CUT','starts_local','2030-07-30T18:00','ends_local','2030-07-30T19:00')))))::text,true);
select set_config('request.jwt.claim.sub',current_setting('test.owner'),true);
set local role authenticated;
select set_config('test.appointment',(public.save_internal_appointment(current_setting('test.payload')::jsonb)->>'id'),true);
select is((public.get_appointment(current_setting('test.appointment')::uuid)->>'total_price'),'100.10','Precio se cuenta una vez aunque haya dos etapas');
select is((public.get_appointment(current_setting('test.appointment')::uuid)->>'deposit_required'),'0','RN09: interna sin adelanto');
select is((public.get_appointment(current_setting('test.appointment')::uuid)->>'source'),'INTERNAL','Origen interno de servidor');
select is((public.get_appointment(current_setting('test.appointment')::uuid)->>'status'),'CONFIRMED','Alta confirmada por recepción');
select is(jsonb_array_length(public.get_appointment(current_setting('test.appointment')::uuid)->'items'->0->'stages'),2,'Mismo trabajador puede bañar y cortar');
select is((public.appointment_availability(current_setting('test.employee')::uuid,'2030-07-30','18:00','19:00',true,null,true)->>'interval_covered')::boolean,false,'Agenda descuenta ocupación después18');
select is((public.employee_availability(current_setting('test.employee')::uuid,'2030-07-30','18:00','19:00',true)->>'interval_covered')::boolean,true,'Contrato laboral de Fase3 se conserva separado');
select throws_ok($$select public.save_internal_appointment(current_setting('test.payload')::jsonb)$$,'23P01',null,'No duplicar empleado/mascota');
select is((select count(*)::integer from public.appointments where client_id=current_setting('test.client')::uuid),1,'Duplicado no deja cabecera parcial');
select throws_ok($$select public.save_internal_appointment(jsonb_set(jsonb_set(current_setting('test.payload')::jsonb,'{items,0,stages,0,ends_local}','"2030-07-30T17:00:30"'),'{items,0,stages,1,starts_local}','"2030-07-30T17:00:30"'))$$,'23514',null,'Cada etapa exige minutos enteros, no solo la suma');
select throws_ok($$select public.save_internal_appointment(current_setting('test.payload')::jsonb||'{"total_price":"0"}')$$,'22023',null,'No confiar total del cliente');
select throws_ok($$select public.save_internal_appointment(current_setting('test.payload')::jsonb||'{"source":"ONLINE"}')$$,'22023',null,'No permitir forjar origen');
select throws_ok($$insert into public.appointment_items(appointment_id,pet_id,client_id,service_id,price,duration_minutes,requires_specialist_snapshot) values(current_setting('test.appointment')::uuid,current_setting('test.pet')::uuid,current_setting('test.client')::uuid,current_setting('test.service')::uuid,0,1,false)$$,'42501',null,'Escritura directa revocada incluso owner');
select throws_ok($$select public.save_internal_appointment(current_setting('test.payload')::jsonb,current_setting('test.appointment')::uuid,999)$$,'40001',null,'Versión desactualizada no sobrescribe');
select throws_ok($$select public.save_time_block(jsonb_build_object('employee_id',current_setting('test.employee'),'starts_local','2030-07-30T18:00','ends_local','2030-07-30T19:00','reason','Prueba bloqueo'))$$,'23P01',null,'Nuevo bloqueo no invalida cita');
select is((select count(*)::integer from public.time_blocks where employee_id=current_setting('test.employee')::uuid),0,'Bloqueo rechazado se revierte');
select throws_ok($$select public.save_work_period('business',jsonb_build_object('weekday',2,'start_time','07:00','end_time','16:00'),(select id from public.business_hours where weekday=2 and open_time='07:00' limit 1))$$,'23P01',null,'Cambio comercial no invalida reserva existente');
select throws_ok($$select public.save_employee('{"active":false}',current_setting('test.employee')::uuid)$$,'23P01',null,'No desactivar trabajador reservado');
select throws_ok($$select public.save_employee('{"skill_level":"ASSISTANT"}',current_setting('test.employee')::uuid)$$,'23P01',null,'No retirar habilidad reservada');
select throws_ok($$select public.change_appointment_status(current_setting('test.appointment')::uuid,'IN_PROGRESS',1)$$,'22023',null,'Inicio de atención no anticipado');
select throws_ok($$select public.change_appointment_status(current_setting('test.appointment')::uuid,'COMPLETED',1)$$,'22023',null,'Sin salto a completada');
select throws_ok($$select public.change_appointment_status(current_setting('test.appointment')::uuid,'CANCELLED',1,' ')$$,'22023',null,'Cancelación exige motivo');
select public.save_appointment_internal(current_setting('test.appointment')::uuid,'Observación reservada',1);
select is((public.get_appointment(current_setting('test.appointment')::uuid)->>'version')::integer,2,'Nota interna también controla versión');
select ok(position('Observación reservada' in public.get_appointment(current_setting('test.appointment')::uuid)::text)=0,'Nota interna no aparece en ficha ordinaria');
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.staff'),true);
set local role authenticated;
select is((select count(*)::integer from public.appointments where id=current_setting('test.appointment')::uuid),1,'STAFF lee agenda');
select is((select count(*)::integer from public.appointment_internal where appointment_id=current_setting('test.appointment')::uuid),1,'STAFF lee notas operativas con permiso');
select throws_ok($$select public.save_internal_appointment(current_setting('test.payload')::jsonb)$$,'42501',null,'STAFF no agenda');
select throws_ok($$select public.change_appointment_status(current_setting('test.appointment')::uuid,'CANCELLED',2,'No')$$,'42501',null,'STAFF no cancela');
select throws_ok($$select public.save_appointment_internal(current_setting('test.appointment')::uuid,'No',2)$$,'42501',null,'STAFF no edita notas');
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.owner'),true);
set local role authenticated;
select public.change_appointment_status(current_setting('test.appointment')::uuid,'CANCELLED',2,'Prueba');
select is((select count(*)::integer from public.appointment_items where appointment_id=current_setting('test.appointment')::uuid),1,'Cancelar conserva detalle');
select is((select count(*)::integer from public.appointment_item_staff where item_id in(select id from public.appointment_items where appointment_id=current_setting('test.appointment')::uuid)),2,'Cancelar conserva etapas');
select is((public.appointment_availability(current_setting('test.employee')::uuid,'2030-07-30','18:00','19:00',true,null,true)->>'interval_covered')::boolean,true,'Cancelar libera reserva');
select throws_ok($$select public.change_appointment_status(current_setting('test.appointment')::uuid,'CONFIRMED',3)$$,'22023',null,'Terminal no se reabre');
reset role;
select set_config('request.jwt.claim.sub','',true);
set local role authenticated;
select is((select count(*)::integer from public.appointments where client_id=current_setting('test.client')::uuid),0,'Sin identidad no hay lectura');
select is((select count(*)::integer from public.appointment_internal where appointment_id=current_setting('test.appointment')::uuid),0,'Sin identidad no hay notas');
reset role;
set local role anon;
select throws_ok($$select public.get_appointment(current_setting('test.appointment')::uuid)$$,'42501',null,'Anon sin RPC de agenda');
reset role;
select * from finish();
rollback;
